using System.IO;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using Npgsql;
using PGMS.Desktop;
using PGMS.PostgreSql;

internal static class IdentityColumnOperationDialogChecks
{
    private static T Find<T>(Window w,string name)where T:FrameworkElement=>(T)w.FindName(name);
    private static async Task Modal(Window w,Func<Task> body)
    {
        var done=new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);
        w.Loaded+=async(_,_)=>{try{await body();done.TrySetResult();}catch(Exception ex){done.TrySetException(ex);}finally{if(w.IsVisible)w.Close();}};
        w.ShowDialog();await done.Task;
    }
    private static async Task Capture(Window w,string name,double width,double height,Action<bool,string> check,string milestone="m746")
    {
        w.Width=width;w.Height=height;await w.Dispatcher.InvokeAsync(()=>{},System.Windows.Threading.DispatcherPriority.ApplicationIdle);w.UpdateLayout();var root=(FrameworkElement)w.Content;
        foreach(string action in new[]{"InspectButton","ScriptButton","ApplyButton","CloseButton"}){var b=Find<Button>(w,action);var p=b.TranslatePoint(new Point(),root);check(p.Y>=-0.1 && p.Y+b.ActualHeight<=root.ActualHeight+0.1,"Identity management action fits "+name+"/"+action);}
        check(Find<TextBox>(w,"Preview").ActualHeight>=85,"Identity management SQL remains readable: "+name);
        var bitmap=new RenderTargetBitmap((int)Math.Ceiling(root.ActualWidth),(int)Math.Ceiling(root.ActualHeight),96,96,PixelFormats.Pbgra32);var drawing=new DrawingVisual();using(var dc=drawing.RenderOpen()){var r=new Rect(0,0,root.ActualWidth,root.ActualHeight);dc.DrawRectangle(w.Background,null,r);dc.DrawRectangle(new VisualBrush(root),null,r);}bitmap.Render(drawing);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(bitmap));Directory.CreateDirectory("artifacts/review");using var file=File.Create("artifacts/review/"+milestone+"-"+name+".png");encoder.Save(file);
    }
    private static async Task OpenChild(TableEditDialog parent,Func<IdentityColumnDialog,Task> body)
    {
        Exception? failure=null;bool found=false;var timer=new System.Windows.Threading.DispatcherTimer{Interval=TimeSpan.FromMilliseconds(40)};var deadline=DateTime.UtcNow.AddSeconds(10);
        timer.Tick+=async(_,_)=>
        {
            var child=Application.Current.Windows.OfType<IdentityColumnDialog>().SingleOrDefault(w=>w.Owner==parent);
            if(child is null){if(DateTime.UtcNow>deadline){Console.Error.WriteLine("Identity child did not open.");Environment.Exit(1);}return;}
            if(found)return;found=true;timer.Stop();
            try{await body(child);}catch(Exception ex){failure=ex;}finally{if(child.IsVisible)child.Close();}
        };
        timer.Start();try{await parent.OpenIdentityOperationsAsync();}finally{timer.Stop();}
        if(failure is not null)throw failure;if(!found)throw new InvalidOperationException("Identity navigation did not open the selected column.");
    }
    internal static async Task RunAsync(string connection,Action<bool,string> check)
    {
        string suffix=Guid.NewGuid().ToString("N"),schema="identity_operations_"+suffix,owner="identity_operations_owner_"+suffix,qs=SqlIdentifier.Quote(schema),qo=SqlIdentifier.Quote(owner),table=ObjectSql.Relation(schema,"items");
        await using var admin=new NpgsqlConnection(connection);await admin.OpenAsync();
        async Task Sql(string sql){await using var c=new NpgsqlCommand(sql,admin);await c.ExecuteNonQueryAsync();}
        string limited=new NpgsqlConnectionStringBuilder(connection){Username=owner,Pooling=false}.ConnectionString;
        var layouts=new List<(bool Valid,string Message)>();
        try
        {
            await Sql($"CREATE ROLE {qo} LOGIN;CREATE SCHEMA {qs} AUTHORIZATION {qo};SET ROLE {qo};CREATE TABLE {table}(id integer NOT NULL);INSERT INTO {table} VALUES(17),(27);RESET ROLE");
            var selected=await new TablePropertiesService(limited).InspectAsync(schema,"items");
            var dialog=new IdentityColumnDialog(limited,selected,selected.Columns.Single(c=>c.Name=="id")){ShowInTaskbar=false};
            await Modal(dialog,async()=>
            {
                check(!Find<Button>(dialog,"ApplyButton").IsEnabled,"Identity management requires inspection before Apply");await dialog.InspectAsync();
                check(dialog.Snapshot is{HasIdentity:false} && Find<Button>(dialog,"ApplyButton").IsEnabled,"Identity inspection permits adding generation to an existing NOT NULL integer");
                check(Find<TextBox>(dialog,"Preview").Text.Contains("ADD GENERATED BY DEFAULT AS IDENTITY"),"Identity management previews exact add SQL");
                await dialog.ApplyAsync();check(dialog.WasApplied && dialog.RequiresParentRefresh && dialog.SnapshotIsStale && !Find<Button>(dialog,"ApplyButton").IsEnabled,"Identity Apply marks observation stale and requires parent refresh");
                await dialog.InspectAsync();check(dialog.Snapshot is{HasIdentity:true,Sequence:not null},"Reinspection loads the real internal identity sequence");
                Find<ComboBox>(dialog,"Operation").SelectedIndex=1;await dialog.ApplyAsync();await dialog.InspectAsync();check(dialog.Snapshot!.Generation=="a","WPF changes existing generation to ALWAYS under the identity guard");
                Find<ComboBox>(dialog,"Operation").SelectedIndex=5;
                check(!Find<Button>(dialog,"ApplyButton").IsEnabled,"Identity sequence configuration requires an explicit integer value");
                Find<Button>(dialog,"LoadConfiguredButton").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));
                check(Find<TextBox>(dialog,"ParameterValue").Text=="1" && Find<TextBox>(dialog,"ParameterValue").IsKeyboardFocusWithin && Find<TextBlock>(dialog,"OperationHelp").Text.Contains("does not reset"),"Configured START loads metadata and explains its difference from restart");
                Find<TextBox>(dialog,"ParameterValue").Text="10";await dialog.ApplyAsync();check(!Find<Button>(dialog,"LoadConfiguredButton").IsEnabled,"Stale identity metadata cannot be loaded after Apply");await dialog.InspectAsync();
                check(Find<ComboBox>(dialog,"Operation").SelectedIndex==5 && Find<TextBox>(dialog,"ParameterValue").Text=="10" && dialog.Snapshot!.Sequence!.Start==10,"Reinspection preserves operation and explicit proposal while updating START");
                Find<ComboBox>(dialog,"Operation").SelectedIndex=4;Find<TextBox>(dialog,"ParameterValue").Text="0";check(!Find<Button>(dialog,"ApplyButton").IsEnabled,"Identity UI refuses zero increment before SQL");Find<TextBox>(dialog,"ParameterValue").Text="2";await dialog.ApplyAsync();await dialog.InspectAsync();check(dialog.Snapshot!.Sequence!.Increment==2,"Identity UI applies a real sequence increment");
                Find<ComboBox>(dialog,"Operation").SelectedIndex=6;Find<Button>(dialog,"LoadConfiguredButton").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));check(Find<TextBox>(dialog,"ParameterValue").Text=="1" && Find<TextBox>(dialog,"MaximumValue").Text=="2147483647","Identity bounds load both inspected values");
                Find<TextBox>(dialog,"ParameterValue").Text="11";Find<TextBox>(dialog,"MaximumValue").Text="200";check(!Find<Button>(dialog,"ApplyButton").IsEnabled,"Identity UI bounds must retain configured START");Find<TextBox>(dialog,"ParameterValue").Text="1";
                await Capture(dialog,"bounds-normal",760,720,(v,m)=>layouts.Add((v,m)),"m749");Find<ScrollViewer>(dialog,"FormScroller").ScrollToEnd();await Capture(dialog,"bounds-small",650,600,(v,m)=>layouts.Add((v,m)),"m749");
                await dialog.ApplyAsync();await dialog.InspectAsync();check(dialog.Snapshot!.Sequence is{Minimum:1,Maximum:200},"Identity UI applies the exact reviewed bounds");
                Find<ComboBox>(dialog,"Operation").SelectedIndex=7;Find<TextBox>(dialog,"ParameterValue").Text="0";check(!Find<Button>(dialog,"ApplyButton").IsEnabled,"Identity UI refuses a nonpositive cache");Find<TextBox>(dialog,"ParameterValue").Text="3";await dialog.ApplyAsync();await dialog.InspectAsync();check(dialog.Snapshot!.Sequence!.Cache==3 && Find<TextBlock>(dialog,"OperationHelp").Text.Contains("gaps"),"Identity cache Apply updates metadata with a gaps warning");
                Find<ComboBox>(dialog,"Operation").SelectedIndex=8;Find<Button>(dialog,"LoadConfiguredButton").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));check(Find<CheckBox>(dialog,"CycleValue").IsChecked==false,"Identity cycle loads its inspected disabled state");Find<CheckBox>(dialog,"CycleValue").IsChecked=true;await dialog.ApplyAsync();await dialog.InspectAsync();check(dialog.Snapshot!.Sequence!.Cycle && Find<TextBlock>(dialog,"OperationHelp").Text.Contains("does not ensure uniqueness"),"Identity cycle Apply is explicit about possible duplicate values");
                await Capture(dialog,"cycle-small",650,600,(v,m)=>layouts.Add((v,m)),"m749");
                Find<ComboBox>(dialog,"Operation").SelectedIndex=2;
                check(!Find<Button>(dialog,"ApplyButton").IsEnabled,"Restart requires an explicit value");Find<TextBox>(dialog,"RestartValue").Text="2147483648";check(!Find<Button>(dialog,"ApplyButton").IsEnabled,"Out-of-bounds restart is refused before confirmation");
                Find<TextBox>(dialog,"RestartValue").Text="100";
                await Capture(dialog,"restart-normal",760,720,(v,m)=>layouts.Add((v,m)));Find<ScrollViewer>(dialog,"FormScroller").ScrollToEnd();await Capture(dialog,"restart-small",650,600,(v,m)=>layouts.Add((v,m)));
                await SequenceConfirmationChecks.RespondAsync(dialog,dialog.ApplyAsync,false,check);check(!dialog.SnapshotIsStale && Find<TextBlock>(dialog,"Feedback").Text.Contains("Nothing was sent"),"Native No preserves the restart proposal without sending SQL");
                await SequenceConfirmationChecks.RespondAsync(dialog,dialog.ApplyAsync,true,check);check(dialog.SnapshotIsStale,"Confirmed restart requires reinspection before repetition");
                await using(var c=new NpgsqlCommand($"INSERT INTO {table} DEFAULT VALUES RETURNING id",admin))check(Convert.ToInt64(await c.ExecuteScalarAsync())==100,"WPF confirmed restart sets the next actual inserted value");
                await dialog.InspectAsync();Find<ComboBox>(dialog,"Operation").SelectedIndex=3;
                await Capture(dialog,"drop-small",650,600,(v,m)=>layouts.Add((v,m)));
                await SequenceConfirmationChecks.RespondAsync(dialog,dialog.ApplyAsync,false,check);check(!dialog.SnapshotIsStale,"Native No also preserves identity on Drop");
                await SequenceConfirmationChecks.RespondAsync(dialog,dialog.ApplyAsync,true,check);await dialog.InspectAsync();check(dialog.Snapshot is{HasIdentity:false,Nullable:false,Sequence:null},"Confirmed Drop preserves NOT NULL and removes only identity generation");
                await using(var c=new NpgsqlCommand($"SELECT array_agg(id ORDER BY id)::text FROM {table}",admin))check((string)(await c.ExecuteScalarAsync())! =="{17,27,100}","Identity management preserves all existing row values");
            });
            var script=new IdentityColumnDialog(limited,selected,selected.Columns.Single(c=>c.Name=="id")){ShowInTaskbar=false};
            await Modal(script,async()=>{await script.InspectAsync();Find<ComboBox>(script,"Operation").SelectedIndex=1;Find<Button>(script,"ScriptButton").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));});
            check(script.ScriptSql!.Contains("ADD GENERATED ALWAYS AS IDENTITY") && !script.WasApplied,"Identity Script returns SQL without applying it");
            check(!(await new IdentityColumnService(limited).InspectAsync(schema,"items","id")).HasIdentity,"Identity Script leaves PostgreSQL unchanged");
            var parentScript=new TableEditDialog(limited,inspectedTable:selected,column:"id"){ShowInTaskbar=false};
            await Modal(parentScript,async()=>
            {
                check(Find<Button>(parentScript,"IdentityOperationsButton").IsVisible && Find<Button>(parentScript,"IdentityOperationsButton").IsEnabled,"Inspected integer column exposes identity navigation");
                await OpenChild(parentScript,async child=>{await child.InspectAsync();Find<Button>(child,"ScriptButton").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));});
            });
            check(parentScript.ScriptSql!.Contains("ADD GENERATED BY DEFAULT AS IDENTITY") && !parentScript.WasApplied,"Parent propagates child SQL to the editor without applying it");
            var parentApply=new TableEditDialog(limited,inspectedTable:selected,column:"id"){ShowInTaskbar=false};
            await Modal(parentApply,async()=>{await OpenChild(parentApply,async child=>{await child.InspectAsync();await child.ApplyAsync();});check(parentApply.WasApplied && parentApply.InspectedTable!.Columns.Single(c=>c.Name=="id").Identity=="By default","Parent reports child Apply and refreshes its inspected identity metadata");});
            await Sql($"ALTER TABLE {table} ALTER COLUMN id DROP IDENTITY");
            var stale=new IdentityColumnDialog(limited,selected,selected.Columns.Single(c=>c.Name=="id")){ShowInTaskbar=false};
            await Modal(stale,async()=>{await stale.InspectAsync();await Sql($"ALTER TABLE {table} DROP COLUMN id;ALTER TABLE {table} ADD COLUMN id integer NOT NULL DEFAULT 0");await stale.ApplyAsync();check(!stale.WasApplied && stale.SnapshotIsStale,"WPF refuses a replaced column before identity DDL");await stale.InspectAsync();check(stale.SnapshotIsStale && !Find<Button>(stale,"ApplyButton").IsEnabled,"Reinspection cannot silently transfer the original parent selection to a replacement column");});
            foreach(var result in layouts)check(result.Valid,result.Message);
        }
        finally{await Sql($"RESET ROLE;DROP SCHEMA IF EXISTS {qs} CASCADE;DROP ROLE IF EXISTS {qo}");}
    }
}
